public with sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;
    private static final Integer MAX_CHAIN_DEPTH = 250;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds != null ? new List<Id>(accountIds) : new List<Id>();
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return enqueueNext(accountIds);
    }

    public void execute(QueueableContext context) {
        if (this.accountIds == null || this.accountIds.isEmpty()) {
            return;
        }

        List<Id> currentBatch = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        Integer totalSize = this.accountIds.size();
        for (Integer i = 0; i < totalSize; i++) {
            if (i < BATCH_SIZE) {
                currentBatch.add(this.accountIds[i]);
            } else {
                remainingIds.add(this.accountIds[i]);
            }
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :currentBatch
        ];

        for (Account acc : accountsToUpdate) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= HOT_THRESHOLD) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= WARM_THRESHOLD) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        if (!remainingIds.isEmpty()) {
            enqueueNext(remainingIds);
        }
    }

    private static Id enqueueNext(List<Id> ids) {
        AccountScoringJob job = new AccountScoringJob(ids);
        Boolean hasMaxDepth = false;
        try {
            hasMaxDepth = AsyncInfo.hasMaxStackDepth();
        } catch (System.AsyncException e) {
            hasMaxDepth = false;
        }

        if (!hasMaxDepth) {
            AsyncOptions options = new AsyncOptions();
            options.MaximumQueueableStackDepth = MAX_CHAIN_DEPTH;
            return System.enqueueJob(job, options);
        }
        return System.enqueueJob(job);
    }
}
