global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';

    private static Set<Id> processedOpportunityIds = new Set<Id>();
    private static Set<String> closedWonStages;

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isAfterInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isAfterUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        if (!isAfterInsert && !isAfterUpdate) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (isAfterUpdate && oldlist != null) {
            for (SObject sObj : oldlist) {
                Opportunity oldOpp = (Opportunity) sObj;
                if (oldOpp != null && oldOpp.Id != null) {
                    oldMap.put(oldOpp.Id, oldOpp);
                }
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity opp = (Opportunity) newlist[i];

            if (!isMajorGiftQualified(opp)) {
                continue;
            }

            if (isAfterUpdate) {
                Opportunity oldOpp = (opp.Id != null && oldMap.containsKey(opp.Id))
                    ? oldMap.get(opp.Id)
                    : (oldlist != null && i < oldlist.size() ? (Opportunity) oldlist[i] : null);
                if (isMajorGiftQualified(oldOpp)) {
                    continue;
                }
            }

            if (opp.Id != null && processedOpportunityIds.contains(opp.Id)) {
                continue;
            }

            tasksToInsert.add(buildFollowUpTask(opp));

            if (opp.Id != null) {
                processedOpportunityIds.add(opp.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private static Boolean isMajorGiftQualified(Opportunity opp) {
        if (opp == null || opp.Amount == null || opp.Amount < MAJOR_GIFT_THRESHOLD) {
            return false;
        }
        return isClosedWon(opp);
    }

    private static Boolean isClosedWon(Opportunity opp) {
        if (opp.IsWon == true) {
            return true;
        }
        if (String.isBlank(opp.StageName)) {
            return false;
        }
        if (opp.StageName.equalsIgnoreCase('Closed Won')) {
            return true;
        }
        if (closedWonStages == null) {
            closedWonStages = new Set<String>();
            for (OpportunityStage stage : [SELECT ApiName, MasterLabel FROM OpportunityStage WHERE IsClosed = true AND IsWon = true]) {
                if (stage.ApiName != null) {
                    closedWonStages.add(stage.ApiName.toLowerCase());
                }
                if (stage.MasterLabel != null) {
                    closedWonStages.add(stage.MasterLabel.toLowerCase());
                }
            }
        }
        return closedWonStages.contains(opp.StageName.toLowerCase());
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Date closeDate = opp.CloseDate != null ? opp.CloseDate : Date.today();
        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = closeDate.addDays(3)
        );
    }
}
