            fields.add('Salary__c');
        }
        if (Schema.sObjectType.FB_Employee__c.fields.Personal_Email__c.isAccessible()) {
            fields.add('Personal_Email__c');
        }

        String soql = 'SELECT ' + String.join(fields, ', ') + ' FROM FB_Employee__c ORDER BY Name ASC';

        List<FB_Employee__c> employees = (List<FB_Employee__c>) Database.query(
            soql,
            AccessLevel.USER_MODE
        );

